package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Scarab with its own model and texture. Generated by shadw-mod mob. */
public class ScarabRenderer extends MobRenderer<Scarab, ScarabModel.State, ScarabModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/scarab.png");

	public ScarabRenderer(EntityRendererProvider.Context context) {
		super(context, new ScarabModel(context.bakeLayer(ScarabModel.LAYER)), 0.4F);
	}

	@Override
	public ScarabModel.State createRenderState() {
		return new ScarabModel.State();
	}

	@Override
	public void extractRenderState(Scarab entity, ScarabModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(ScarabModel.State state) {
		return TEXTURE;
	}
}
